// One case per process, so the cases do not share a heap:
//   for c in literal setters define proto null; do node --allow-natives-syntax repro.js $c 10; done
//   for c in today direct cached today-null cached-null; do node --allow-natives-syntax repro.js $c 10; done
const { make } = require('./build/Release/binding.node');
const { makeV8 } = require('./build/Release/cached.node');

const which = process.argv[2];
const width = Number(process.argv[3] ?? 10);
const count = 100_000;
const names = Array.from({ length: width }, (_, i) => `k${i}`);
const values = names.map((_, i) => i + 0.5);

// Every case stores the same values; only the way the objects are made differs.
const literals = new Function('n', 'v', `
  const a = new Array(n);
  for (let i = 0; i < n; i++) a[i] = { ${names.map((k, j) => `${k}: v[${j}]`).join(', ')} };
  return a;`);
const read = new Function('a', `
  let s = 0;
  for (let i = 0; i < a.length; i++) { const o = a[i]; s += ${names.map((k) => `o.${k}`).join(' + ')}; }
  return s;`);

const build = {
  // Node-API, binding.c
  literal: () => literals(count, values),
  setters: () => make(names, values, undefined, count, 1),
  define: () => make(names, values, undefined, count, 2),
  proto: () => make(names, values, Object.prototype, count),
  null: () => make(names, values, undefined, count),
  // V8 API, cached.cc: one harness for today's body, Object::New alone and the cache
  today: () => makeV8(names, values, Object.prototype, count, 0),
  direct: () => makeV8(names, values, Object.prototype, count, 1),
  cached: () => makeV8(names, values, Object.prototype, count, 2),
  'today-null': () => makeV8(names, values, undefined, count, 0),
  'cached-null': () => makeV8(names, values, undefined, count, 2),
}[which];

// Median ns per property of `runs` calls of f; returns the last result too.
function time(f, runs) {
  const times = [];
  let out;
  for (let i = 0; i < runs; i++) {
    const t0 = process.hrtime.bigint();
    out = f();
    times.push(Number(process.hrtime.bigint() - t0));
  }
  times.sort((x, y) => x - y);
  return [times[times.length >> 1] / (count * width), out];
}

build();
const [buildNs, objects] = time(build, 11);
for (let i = 0; i < 5; i++) read(objects);
const [readNs] = time(() => read(objects), 21);
const fast = %HasFastProperties(objects[0]);
const sameMap = %HaveSameMap(objects[0], objects[count - 1]);
console.log(
  `${process.version} ${which.padEnd(11)} ${width} properties: fast=${fast} sameMap=${sameMap} ` +
    `build ${buildNs.toFixed(1)} ns, read ${readNs.toFixed(2)} ns per property`,
);
